// Image-phase acceptance against the real app. This does not award v1.
// Optional HG_MAPLIBRE_CACHE_DIR serves the exact upstream MapLibre 3.6.2 files
// when the browser cannot reach its CDN; it must never contain mocks.
import assert from 'node:assert/strict';import fs from 'node:fs';import path from 'node:path';import http from 'node:http';import { chromium } from 'playwright';
const root=process.cwd();
const records=JSON.parse(fs.readFileSync('reports/place-production/oslo-aav-photos-20261026.json')).records;
const mime={'.html':'text/html','.js':'text/javascript','.mjs':'text/javascript','.json':'application/json','.css':'text/css','.webp':'image/webp','.png':'image/png','.jpg':'image/jpeg','.svg':'image/svg+xml','.woff2':'font/woff2'};
const server=http.createServer((req,res)=>{const p=path.resolve(root,'.'+(decodeURIComponent(new URL(req.url,'http://localhost').pathname)||'/index.html'));if(!p.startsWith(root+'/')||!fs.existsSync(p)||!fs.statSync(p).isFile()){res.writeHead(404);res.end();return;}res.writeHead(200,{'Content-Type':mime[path.extname(p)]||'application/octet-stream'});fs.createReadStream(p).pipe(res)});await new Promise(r=>server.listen(0,'127.0.0.1',r));
const out=path.join(root,'artifacts/oslo-aav-photos-browser');fs.mkdirSync(out,{recursive:true});const checks=[];const browser=await chromium.launch({headless:true,executablePath:process.env.CHROME_BIN||undefined,args:['--no-sandbox','--disable-dev-shm-usage']});
try{for(const [mode,width,height] of [['mobile',390,844],['desktop',1440,1000]]){const ctx=await browser.newContext({viewport:{width,height},isMobile:mode==='mobile',hasTouch:mode==='mobile'});await ctx.addInitScript(()=>{localStorage.setItem('hg_onboarding_shown_v1','1');localStorage.setItem('HG_TEST_MODE','1')});if(process.env.HG_MAPLIBRE_CACHE_DIR) await ctx.route('https://unpkg.com/maplibre-gl@3.6.2/dist/*',route=>route.fulfill({path:path.join(process.env.HG_MAPLIBRE_CACHE_DIR,new URL(route.request().url()).pathname.split('/').pop()),contentType:route.request().url().endsWith('.css')?'text/css':'text/javascript'}));const page=await ctx.newPage();
for(const r of records){const id=r.place_id;const row={id,mode};try{await page.goto('http://127.0.0.1:'+server.address().port+'/index.html?hgTest=1#/place/'+id,{waitUntil:'domcontentloaded',timeout:60000});await page.waitForFunction(id=>window.__HG_APP_READY__===true&&window.__HG_ROUTER_STARTED__===true&&document.querySelector('#placeCard')?.dataset.currentPlaceId===id,id,{timeout:60000});await page.evaluate(async id=>{const p=window.HGPlaceOpen?.getPlace?.(id);if(!p)throw new Error('Canonical hydration missing');await window.openPlaceCard(p)},id);await page.waitForFunction(()=>document.querySelector('#placeCard')?.classList.contains('is-open'),null,{timeout:20000});await page.waitForFunction(()=>document.querySelector('#pcFrontImage')?.complete&&document.querySelector('#pcFrontImage')?.naturalWidth>0,null,{timeout:20000});row.front=await page.locator('#pcFrontImage').evaluate(el=>({src:el.currentSrc,width:el.naturalWidth,height:el.naturalHeight,box:el.getBoundingClientRect().toJSON()}));assert.ok(row.front.src.endsWith(r.outputs.frontImage));assert.equal(row.front.width,900);assert.equal(row.front.height,1350);assert.ok(row.front.box.width>40&&row.front.box.height>60);row.hero=await page.evaluate(async src=>{const im=new Image();im.src=src;await im.decode();return{width:im.naturalWidth,height:im.naturalHeight}},r.outputs.image);assert.deepEqual(row.hero,{width:1400,height:900});await page.locator('#pcFrontImage').scrollIntoViewIfNeeded();await page.waitForTimeout(500);row.cardVisible=await page.locator('#placeCard').evaluate(el=>el.classList.contains('is-open')&&!el.classList.contains('is-hidden')&&getComputedStyle(el).visibility==='visible');assert.equal(row.cardVisible,true);await page.screenshot({path:out+'/'+id+'-'+mode+'.png',fullPage:false});row.appReady=await page.evaluate(()=>window.__HG_APP_READY__);row.status='PASS';}catch(e){row.status='FAIL';row.error=String(e)}checks.push(row);console.log(JSON.stringify(row));}
await ctx.close();}}finally{await browser.close();server.close();fs.writeFileSync(out+'/report.json',JSON.stringify({scope:'Real app image rendering only; quiz, Fagverk and v1 not approved',checks},null,2)+'\n')}
if(checks.some(r=>r.status==='FAIL'))process.exitCode=1;
